<h2>Compare exposure settings in stops</h2><p class="lead">Compare two shutter, aperture and ISO combinations and see the net exposure change.</p><div class="notice">A one-stop change is a factor of two in exposure. Aperture changes affect exposure with the square of the f-number ratio.</div><div class="form-grid"><div class="field"><label for="t1">Baseline shutter time (seconds)</label><input id="t1" type="number" value="0.008" min="0.000001" step="any"><small class="helper">Example: 1/125 s = 0.008</small></div><div class="field"><label for="n1">Baseline aperture</label><input id="n1" type="number" value="4" min="0.5" step="any"></div><div class="field"><label for="iso1">Baseline ISO</label><input id="iso1" type="number" value="100" min="1" step="any"></div><div class="field"><label for="t2">New shutter time (seconds)</label><input id="t2" type="number" value="0.004" min="0.000001" step="any"></div><div class="field"><label for="n2">New aperture</label><input id="n2" type="number" value="2.8" min="0.5" step="any"></div><div class="field"><label for="iso2">New ISO</label><input id="iso2" type="number" value="100" min="1" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Shutter change</span><strong id="shutter">—</strong></div><div class="metric"><span>Aperture change</span><strong id="aperture">—</strong></div><div class="metric"><span>ISO change</span><strong id="iso">—</strong></div><div class="metric"><span>Net exposure change</span><strong id="net">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('shutter').textContent='—';$('aperture').textContent='—';$('iso').textContent='—';$('net').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const t1=num('t1'),n1=num('n1'),i1=num('iso1'),t2=num('t2'),n2=num('n2'),i2=num('iso2');if(!(t1>0&&n1>0&&i1>0&&t2>0&&n2>0&&i2>0))throw 0;const ss=Math.log2(t2/t1),as=2*Math.log2(n1/n2),is=Math.log2(i2/i1),net=ss+as+is;const fs=v=>(v>=0?'+':'')+fmt(v,2)+' stops';$('shutter').textContent=fs(ss);$('aperture').textContent=fs(as);$('iso').textContent=fs(is);$('net').textContent=fs(net);$('note').textContent=Math.abs(net)<0.05?'The two settings are essentially exposure-equivalent by this model.':'Positive means a brighter recorded result; negative means darker, before scene or processing changes.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
